package com.vandorlabs.neoforge.screen;


import net.minecraft.nbt.*;
/** Actual standalone row saved/configuration normalization, including half-height capacity. */
public final class ScreenControlChecks {
 public static void main(String[] args)throws Exception{java.security.MessageDigest hash=java.security.MessageDigest.getInstance("SHA-256");int cases=0;
  for(int half=0;half<2;half++)for(int count=0;count<=10;count++)for(int kind=0;kind<16;kind++){
   CompoundTag input=input(count,kind);NativeScreenControls contents=NativeScreenControls.read(input,half==0?8:4);CompoundTag save=new CompoundTag();contents.write(save);String text=canonical(save)+canonical(contents.configuration())+NativeScreenControls.validConfiguration(input);hash.update(text.getBytes("UTF-8"));cases++;
  }CompoundTag opaque=input(2,10);opaque.putString("Foreign","root");opaque.getList("Rows",10).getCompound(0).putString("FutureRow","opaque");CompoundTag before=opaque.copy();var snapshot=new NativeScreenControls.Saved(opaque,8);opaque.remove("Rows");if(!snapshot.unchanged().equals(before)||!snapshot.edited(snapshot.controls).equals(before))throw new AssertionError("Original control snapshot lost");CompoundTag merged=before.copy();snapshot.controls.write(merged);if(!merged.getList("Rows",10).getCompound(0).getString("FutureRow").equals("opaque"))throw new AssertionError("Unknown row key lost");CompoundTag config=snapshot.controls.configuration();for(int i=0;i<config.getList("Rows",10).size();i++)for(String key:new String[]{"Levels","Level","LatchedChannels","Active","PulseUntil"})if(config.getList("Rows",10).getCompound(i).contains(key))throw new AssertionError("Configuration copied active output ownership");try{snapshot.controls.rows().clear();throw new AssertionError("Mutable row list");}catch(UnsupportedOperationException expected){}StringBuilder out=new StringBuilder();for(byte b:hash.digest())out.append(String.format("%02x",b&255));if(!out.toString().equals("a2e06f4e901b2e7d6b88bcbc83fb4fefbc6f506db945ec70949ea75f0643c274"))throw new AssertionError("Native controls differ from actual "+out);System.out.println("Native Screen controls parity PASS cases="+cases+" sha256="+out);}
 public static CompoundTag input(int count,int kind){CompoundTag root=new CompoundTag();root.putBoolean("Enabled",true);if(kind!=0)root.putString("Title",kind==1?"bad\u00a7title":kind==2?"": "Controls");ListTag rows=new ListTag();for(int i=0;i<count;i++){CompoundTag row=new CompoundTag();row.putString("Label",kind==3?" ":kind==4?"abcdefghijklmnopqrstuvwxy":kind==5?"bad\nlabel":" Row "+i+" ");row.putIntArray("RedstoneChannels",kind==6?new int[]{-1}:new int[]{32,31,32});row.putBoolean("Slider",kind==7||kind==8||kind==9);row.putBoolean("Pulse",kind==8||kind==10||kind==11);if(kind!=0){row.putInt("Min",kind==9?15:kind==12?-1:0);row.putInt("Max",kind==9?0:kind==13?99:15);}row.putIntArray("Levels",new int[]{kind==14?-1:6,kind==15?99:12});row.putInt("Level",kind==14?-1:kind==15?99:7);row.putIntArray("LatchedChannels",new int[]{31,99});row.putBoolean("Active",true);row.putLong("PulseUntil",kind==11?-3:123);rows.add(row);}root.put("Rows",rows);return root;}
 private static String canonical(Tag tag){if(tag instanceof CompoundTag){CompoundTag compound=(CompoundTag)tag;StringBuilder out=new StringBuilder("{");for(String key:new java.util.TreeSet<String>(compound.getAllKeys()))out.append(key).append(':').append(canonical(compound.get(key))).append(';');return out.append('}').toString();}if(tag instanceof ListTag){ListTag list=(ListTag)tag;StringBuilder out=new StringBuilder("[");for(int i=0;i<list.size();i++)out.append(canonical(list.get(i))).append(';');return out.append(']').toString();}return tag.toString();}
}
